// Writes src/photophonique/elements.h from web/elements/*.js: each element gzipped
// into a byte array, for WebUi::asset(..., gzipped = true) on the device
// (docs/DESIGN.md section 7.1). Run after editing an element:
//
//   node web/build.mjs
//
// The header is committed, so building the firmware needs no Node.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';

const dir = new URL('./elements/', import.meta.url);
const out = new URL('../src/photophonique/elements.h', import.meta.url);

let header = `#pragma once
// Generated by web/build.mjs from web/elements/. Do not edit.
#include <stddef.h>
#include <stdint.h>

namespace photophonique::elements {
`;
for (const file of readdirSync(dir).filter((f) => f.endsWith('.js')).sort()) {
  const js = readFileSync(new URL(file, dir));
  // mtime 0: the same source gives the same bytes.
  const gz = gzipSync(js, { level: 9 });
  gz.writeUInt32LE(0, 4);
  const name = file.replace(/\.js$/, '').replace(/[^A-Za-z0-9]+(.)?/g, (_, c) => (c ? c.toUpperCase() : ''));
  const bytes = [...gz].map((b) => `0x${b.toString(16).padStart(2, '0')}`);
  const rows = [];
  for (let i = 0; i < bytes.length; i += 16) rows.push(`    ${bytes.slice(i, i + 16).join(', ')},`);
  header += `
// ${file}: ${js.length} B, ${gz.length} B gzipped.
inline constexpr const char* k${name[0].toUpperCase()}${name.slice(1)}Path = "/ext/${file}";
inline constexpr uint8_t k${name[0].toUpperCase()}${name.slice(1)}[] = {
${rows.join('\n')}
};
`;
  console.log(`${file}: ${js.length} B → ${gz.length} B gzipped`);
}
header += '\n}  // namespace photophonique::elements\n';
writeFileSync(out, header);
console.log(`wrote ${out.pathname}`);
